// ======================
// 🎮 SCRIPT - Jogos de Estratégia
// ======================

document.addEventListener('DOMContentLoaded', function() {
    console.log('♟️ Site carregado! Que comece a partida!');
        
            // 1. Botão voltar ao topo
                criarBotaoTopo();

                    // 2. Animação ao rolar a página
                        animarSecoes();

                            // 3. Sistema de dica do dia
                                mostrarDicaDoDia();

                                    // 4. Efeito de clique nos cards
                                        ativarCards();

                                            // 5. Contador de visitas
                                                contadorVisitas();
                                                });

                                                // ------------------------------
                                                // 🔹 1. Botão Voltar ao Topo
                                                // ------------------------------
                                                function criarBotaoTopo() {
                                                    const botao = document.createElement('button');
                                                        botao.innerHTML = '⬆️';
                                                            botao.id = 'btn-topo';
                                                                botao.title = 'Voltar ao topo';
                                                                    
                                                                        botao.style.cssText = `
                                                                                position: fixed;
                                                                                        bottom: 25px;
                                                                                                right: 25px;
                                                                                                        width: 50px;
                                                                                                                height: 50px;
                                                                                                                        border-radius: 50%;
                                                                                                                                background: linear-gradient(135deg, #1e40af, #3b82f6);
                                                                                                                                        color: white;
                                                                                                                                                border: none;
                                                                                                                                                        font-size: 20px;
                                                                                                                                                                cursor: pointer;
                                                                                                                                                                        box-shadow: 0 4px 15px rgba(59, 130, 246, 0.4);
                                                                                                                                                                                opacity: 0;
                                                                                                                                                                                        transition: opacity 0.3s, transform 0.2s;
                                                                                                                                                                                                z-index: 999;
                                                                                                                                                                                                    `;

                                                                                                                                                                                                        document.body.appendChild(botao);

                                                                                                                                                                                                            window.addEventListener('scroll', () => {
                                                                                                                                                                                                                    botao.style.opacity = window.scrollY > 300 ? '1' : '0';
                                                                                                                                                                                                                        });

                                                                                                                                                                                                                            botao.addEventListener('click', () => {
                                                                                                                                                                                                                                    window.scrollTo({ top: 0, behavior: 'smooth' });
                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                            botao.addEventListener('mouseover', () => {
                                                                                                                                                                                                                                                    botao.style.transform = 'scale(1.1)';
                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                            botao.addEventListener('mouseout', () => {
                                                                                                                                                                                                                                                                    botao.style.transform = 'scale(1)';
                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        // ------------------------------
                                                                                                                                                                                                                                                                        // 🔹 2. Animação das Seções
                                                                                                                                                                                                                                                                        // ------------------------------
                                                                                                                                                                                                                                                                        function animarSecoes() {
                                                                                                                                                                                                                                                                            const secoes = document.querySelectorAll('section');
                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                    secoes.forEach(secao => {
                                                                                                                                                                                                                                                                                            secao.style.opacity = '0';
                                                                                                                                                                                                                                                                                                    secao.style.transform = 'translateY(30px)';
                                                                                                                                                                                                                                                                                                            secao.style.transition = 'opacity 0.7s ease, transform 0.7s ease';
                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                    function checarAnimacao() {
                                                                                                                                                                                                                                                                                                                            secoes.forEach(secao => {
                                                                                                                                                                                                                                                                                                                                        const topo = secao.getBoundingClientRect().top;
                                                                                                                                                                                                                                                                                                                                                    const alturaTela = window.innerHeight;
                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                            if (topo < alturaTela - 80) {
                                                                                                                                                                                                                                                                                                                                                                                            secao.style.opacity = '1';
                                                                                                                                                                                                                                                                                                                                                                                                            secao.style.transform = 'translateY(0)';
                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                        window.addEventListener('scroll', checarAnimacao);
                                                                                                                                                                                                                                                                                                                                                                                                                                            checarAnimacao();
                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                            // ------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                            // 🔹 3. Dica de Estratégia do Dia
                                                                                                                                                                                                                                                                                                                                                                                                                                            // ------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                            function mostrarDicaDoDia() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                const dicas = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                        "♟️ Antecipe os movimentos do seu oponente, não apenas reaja.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                "🏗️ Comece garantindo seus recursos antes de atacar.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "⚔️ Concentre suas forças: ataque um ponto de cada vez.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "🧠 Pense várias jogadas à frente, não só na próxima.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "🛡️ Defesa também é estratégia — não subestime a proteção.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "📊 Conheça bem suas peças e seus pontos fortes e fracos.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "⏳ A paciência é uma arma poderosa no jogo de estratégia."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const hoje = new Date().getDate();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const dicaEscolhida = dicas[hoje % dicas.length];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const secaoExemplos = document.getElementById('exemplos');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (secaoExemplos) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const caixaDica = document.createElement('div');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            caixaDica.style.cssText = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        margin-top: 2rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    padding: 1.2rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: linear-gradient(135deg, #1e40af, #3b82f6);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            border-radius: 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border-left: 4px solid #fcd34d;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        caixaDica.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h4 style="color: #fcd34d; margin-bottom: 0.5rem; font-size: 1rem;">💡 Dica de Estratégia do Dia</h4>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p style="color: #e0e7ff; font-style: italic; margin: 0;">${dicaEscolhida}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                secaoExemplos.appendChild(caixaDica);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 🔹 4. Efeito de Clique nos Cards
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function ativarCards() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const cards = document.querySelectorAll('.card, .example');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cards.forEach(card => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        card.style.cursor = 'pointer';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        card.addEventListener('click', function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Remove destaque de todos
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cards.forEach(c => c.style.boxShadow = '');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Destaca o clicado
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        this.style.boxShadow = '0 0 20px rgba(252, 211, 77, 0.4)';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setTimeout(() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                this.style.boxShadow = '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }, 600);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 🔹 5. Contador de Visitas
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function contadorVisitas() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let visitas = parseInt(localStorage.getItem('visitasJogos') || '0') + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                localStorage.setItem('visitasJogos', visitas);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const rodape = document.querySelector('footer');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (rodape) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const contadorEl = document.createElement('p');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        contadorEl.innerHTML = `🎮 Partida nº <strong>${visitas}</strong> — Obrigado por jogar conosco!`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                contadorEl.style.marginTop = '10px';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        contadorEl.style.fontSize = '0.9rem';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                rodape.appendChild(contadorEl);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    